use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failures_retry_until_success_with_bounded_delays() {
    let config = RetryConfig::new(5, 10, 25);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 5 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary outage".into()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 5);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
}

#[test]
fn max_attempts_includes_first_call() {
    let config = RetryConfig::new(3, 1, 100);
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("still failing".into()))
    });

    assert_eq!(result, Err(RetryError::Transient("still failing".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

